-- Shoe sizes, EU 20 to 48, children's and grown-ups'.
INSERT INTO attribute_options (attribute_id, value_code, label, sort_order)
SELECT a.id, 'EU' || n, n::text, n
FROM attributes a, generate_series(20, 48) AS n
WHERE a.code = 'shoe_size';

-- ---------------------------------------------------------------- which category has which

-- A property's rooms, floor and furnishing, and clothes' sizes, go down to the subcategories they
-- fit: a plot has no rooms, a bag no size.
DELETE FROM category_attributes
WHERE category_id = (SELECT id FROM categories WHERE slug = 'prona')
  AND attribute_id IN (SELECT id FROM attributes WHERE code IN ('property_rooms', 'property_floor', 'property_furnished'));
DELETE FROM category_attributes
WHERE category_id = (SELECT id FROM categories WHERE slug = 'veshje-dhe-aksesore')
  AND attribute_id = (SELECT id FROM attributes WHERE code = 'fashion_size');

