-- qendrore", still true of them, until they are saved again.
INSERT INTO listing_attribute_values (listing_id, attribute_id, data_type, value_option_id)
SELECT lo.listing_id, central.attribute_id, 'SELECT', central.id
FROM listing_attribute_options lo
JOIN attribute_options heating ON heating.id = lo.option_id AND heating.value_code = 'HEATING'
JOIN attributes features ON features.id = heating.attribute_id AND features.code = 'property_features'
JOIN listings l ON l.id = lo.listing_id
JOIN attributes kind ON kind.code = 'property_heating'
JOIN attribute_options central ON central.attribute_id = kind.id AND central.value_code = 'CENTRAL'
WHERE l.category_id IN (SELECT category_id FROM effective_category_attributes WHERE attribute_id = kind.id);

DELETE FROM listing_attribute_options lo
USING attribute_options heating, attributes features
WHERE heating.id = lo.option_id AND heating.value_code = 'HEATING'
  AND features.id = heating.attribute_id AND features.code = 'property_features';
DELETE FROM attribute_options heating
USING attributes features
WHERE features.id = heating.attribute_id AND features.code = 'property_features' AND heating.value_code = 'HEATING';

-- With its title deed last of a property's amenities, after the new ones.
UPDATE attribute_options SET sort_order = 200
WHERE value_code = 'TITLE_DEED' AND attribute_id = (SELECT id FROM attributes WHERE code = 'property_features');

-- What a listing said that its category no longer asks, rooms for a plot, a clothes size for a
-- bag, goes, and out of its search words: once gone, as a statement sees the rows as they were
-- when it began.
CREATE TEMPORARY TABLE unasked (listing_id uuid) ON COMMIT DROP;
WITH removed AS (
    DELETE FROM listing_attribute_values v
    USING attributes a, listings l
    WHERE a.code IN ('property_rooms', 'property_floor', 'property_furnished', 'fashion_size')
      AND v.attribute_id = a.id AND l.id = v.listing_id
      AND NOT EXISTS (SELECT 1 FROM effective_category_attributes e WHERE e.category_id = l.category_id AND e.attribute_id = a.id)
    RETURNING v.listing_id
)
INSERT INTO unasked SELECT listing_id FROM removed;
UPDATE listings SET search_extra = listing_search_extra(id)
WHERE id IN (SELECT listing_id FROM unasked);
